import sys

MOD = 998244353

def main():
    # Read all from stdin robustly
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])

    counts = []
    sums = []
    qs = []

    lo = 1
    p10 = 10
    d = 1
    while lo <= N:
        hi = min(N, p10 - 1)
        cnt = hi - lo + 1
        counts.append(cnt)
        sums.append(((lo + hi) * cnt // 2) % MOD)
        qs.append(pow(10, d, MOD))
        lo = p10
        p10 *= 10
        d += 1

    D = len(qs)

    # R(z) = product (1 + q_i z)
    R = [1]
    for q in qs:
        new = [0] * (len(R) + 1)
        for i, v in enumerate(R):
            new[i] = (new[i] + v) % MOD
            new[i + 1] = (new[i + 1] + v * q) % MOD
        R = new

    # H(z) = sum c_i q_i product_{j != i} (1 + q_j z)
    H = [0] * D
    for i, (c, q) in enumerate(zip(counts, qs)):
        poly = [1]
        for j, q2 in enumerate(qs):
            if i == j:
                continue
            new = [0] * (len(poly) + 1)
            for k, v in enumerate(poly):
                new[k] = (new[k] + v) % MOD
                new[k + 1] = (new[k + 1] + v * q2) % MOD
            poly = new

        coef = (c % MOD) * q % MOD
        for k, v in enumerate(poly):
            H[k] = (H[k] + coef * v) % MOD

    inv = [0] * (N + 1)
    if N >= 1:
        inv[1] = 1
    for i in range(2, N + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # P(z) = product (1 + q_i z)^{c_i} = sum e[k] z^k
    # From P'/P = sum c_i q_i / (1 + q_i z), coefficients are generated in O(DN).
    e = [0] * (N + 1)
    de = [0] * (N + 1)
    e[0] = 1

    # Optimization: avoiding min() function overhead and continuous modulos 
    # within the inner loops greatly speeds up execution in Python.
    for k in range(N):
        rhs = 0
        limit1 = k if k < D - 1 else D - 1
        for r in range(limit1 + 1):
            rhs += H[r] * e[k - r]

        limit2 = k if k < D else D
        for r in range(1, limit2 + 1):
            rhs -= R[r] * de[k - r + 1]

        rhs %= MOD
        e[k + 1] = rhs * inv[k + 1] % MOD
        de[k + 1] = e[k + 1] * (k + 1) % MOD

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    weight = [fact[k] * fact[N - 1 - k] % MOD for k in range(N)]

    ans = 0
    for q, total_value in zip(qs, sums):
        # Coefficients of P(z) / (1 + qz), i.e. excluding one number of this digit length.
        cur = 1
        coeff_sum = 0
        for k in range(N):
            if k > 0:
                cur = (e[k] - q * cur) % MOD
            coeff_sum = (coeff_sum + cur * weight[k]) % MOD
        ans = (ans + total_value * coeff_sum) % MOD

    print(ans)

